            long long diff = a[r] - a[l];
            a[l] += diff;
            a[l + 1] += diff;
            ops[l] += diff;
        } else if (a[l] > a[r]) {
            long long diff = a[l] - a[r];
            a[r] += diff;
            a[r - 1] += diff;
            ops[r - 1] += diff;
        }
        ++l;
        --r;
    }

    bool ok = true;
    for (int i = 0; i < n / 2; ++i) {
